-- SQLite: 독립적인 메모리 DB에서 실행하는 예제
CREATE TABLE occupancy(person INTEGER NOT NULL, home TEXT NOT NULL, status TEXT NOT NULL);
INSERT INTO occupancy VALUES (1,'A','current'),(1,'A','current'),(1,'B','ended'),(2,'B','current'),(2,'C','current'),(3,'D','ended');
-- 현재 행을 고른 뒤 사람별 집의 중복을 제거합니다.
SELECT person FROM occupancy WHERE status='current'
GROUP BY person HAVING COUNT(DISTINCT home)>=2 ORDER BY person;
